{
  "name": "usb_ep0_send_data_phase",
  "confidence": "medium",
  "docstring": "Handles the USB endpoint 0 control-IN data phase by updating expected/sent length counters in the EP0 state structure and logging setup or length errors.",
  "subsystem": "hal",
  "var_renames": {
    "v2": "arg_high",
    "v15": "ep0_state",
    "v58": "ep0_sent_len",
    "v60": "ep0_new_sent_len"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "USB EP0 state byte (observed values include 2=error, 4=data transfer, 5=complete)"
    },
    {
      "offset": 8,
      "meaning": "uint16_t expected/total endpoint 0 IN data length"
    },
    {
      "offset": 10,
      "meaning": "uint16_t bytes already sent on endpoint 0 IN data phase"
    }
  ]
}
